import React from "react"
import { CheckCircleIcon } from "@phosphor-icons/react"
import { Chip } from "@sb-components/atoms/chips/Chip/Chip"
import { Breadcrumbs } from "@sb-components/atoms/navigation/Breadcrumbs/Breadcrumbs"
import { Typography } from "@sb-components/atoms/text/Typography/Typography"
import { SurfaceCardList } from "@sb-components/composites/cards/SurfaceCard/SurfaceCard"
import { PageHeader } from "@sb-components/composites/layout/Page/Page"
import { StackH, StackV } from "@sb-components/frames/Stack/Stack"

/**
 * `ContentHeader` — the lesson-identity cluster atop the reading screen: a
 * `PageHeader` cluster carrying read state, reading time, challenge count, and
 * learning outcomes. One chip per cluster (`starci-fe/no-adjacent-chip`): read
 * state takes the chip, reading time and challenge count ride as muted text with
 * an inline icon. `isRead` is a state; losing the outcomes card and `isSkeleton`
 * are each their own leaf. The breadcrumb trail always exists.
 */

/** One breadcrumb link — plain data, the block builds the atom from it. */
export interface ContentHeaderCrumb {
    /** Stable React key. */
    key: string
    /** Display label. */
    label: string
    /** Has a handler → the crumb is pressable; the current page leaves it out. */
    onPress?: () => void
}

/** One line of "what you'll learn" — plain data, the block builds the row. */
export interface ContentHeaderOutcome {
    /** Stable React key. */
    key: string
    /** The outcome sentence, already localized by the caller (blocks carry no i18n). */
    text: string
}

/** Props for {@link ContentHeader}. */
export interface ContentHeaderProps {
    /** Breadcrumb trail as DATA — the block builds `Breadcrumbs` itself. */
    breadcrumbItems?: Array<ContentHeaderCrumb>
    /** Lesson title. */
    title: string
    /** One-sentence summary of the lesson. */
    description?: string
    /**
     * `true` → the learner has finished this lesson. This is the ONE classifying
     * fact in the meta cluster, so it is the one that gets a chip.
     */
    isRead?: boolean
    /** Estimated reading time in MINUTES — the block adds the word itself. */
    minutesRead?: number
    /** How many challenges hang off this lesson — the block adds the word itself. */
    challengeCount?: number
    /**
     * The "what you'll learn" lines. Empty or omitted → the whole section is not
     * drawn at all: a lesson with no stated outcomes should say nothing, not show
     * an empty card.
     */
    outcomes?: Array<ContentHeaderOutcome>
    /**
     * `true` → every composed atom switches to its own shimmer. The flag FLOWS
     * DOWN into the real atoms rather than building a parallel skeleton tree
     * (§12c), so the shimmer keeps the exact box of the thing it replaces.
     */
    isSkeleton?: boolean
}

/**
 * Lesson identity cluster at the top of the reading screen. See the file header
 * for the full contract.
 *
 * @param props - {@link ContentHeaderProps}
 */
const ContentHeader = ({
    breadcrumbItems,
    title,
    description,
    isRead = false,
    minutesRead,
    challengeCount,
    outcomes,
    isSkeleton = false,
}: ContentHeaderProps) => {
    const hasOutcomes = isSkeleton || (outcomes?.length ?? 0) > 0

    return (
        <StackV
            identity={{ tier: "block", component: "ContentHeader" }}
            gap={6}
            principle="sibling-stack"
            explain="Page identity cluster and outcomes card are same-kind peers on the lesson header — not group-boundary, because they are repeating header sections rather than nested groups."
            isSkeleton={isSkeleton}
            items={[
                () => (
                    <PageHeader
                        isSkeleton={isSkeleton}
                        breadcrumb={() =>
                            isSkeleton || breadcrumbItems?.length ? (
                                // Hold: no hug-width frame for breadcrumb measure (`w-fit` parent placement).
                                <div className="w-fit">
                                    <Breadcrumbs
                                        collapseOnMobile
                                        collapseFrom={4}
                                        items={breadcrumbItems ?? []}
                                        isSkeleton={isSkeleton}
                                    />
                                </div>
                            ) : undefined
                        }
                        title={title}
                        description={description}
                        meta={() =>
                            <StackH
                                gap={3}
                                align="center"
                                principle="sibling-stack"
                                explain="Same-kind peer stack — not group-boundary, because these items are repeating siblings rather than section groups."
                                isSkeleton={isSkeleton}
                                items={[
                                    ...(isSkeleton ? [() => (
                                        <Chip isSkeleton />
                                    )] : isRead ? [() => (
                                        <Chip
                                            tone="success"
                                            icon={CheckCircleIcon}
                                            text="Read"
                                        />
                                    )] : []),
                                    ...(isSkeleton ? [() => (
                                        <Typography size="xs" color="muted" isSkeleton />
                                    )] : [
                                        ...(minutesRead != null ? [() => (
                                            <Typography
                                                size="xs"
                                                color="muted"
                                                text={`${minutesRead} min read`}
                                            />
                                        )] : []),
                                        ...(challengeCount != null ? [() => (
                                            <Typography
                                                size="xs"
                                                color="muted"
                                                text={`${challengeCount} challenges`}
                                            />
                                        )] : []),
                                    ]),
                                ]}
                            />
                        }
                    />
                ),
                ...(hasOutcomes ? [() => (
                    <SurfaceCardList
                        label="What you will learn"
                        isSkeleton={isSkeleton}
                        items={(outcomes ?? []).map((outcome) => ({
                            key: outcome.key,
                            leadingIcon: CheckCircleIcon,
                            leadingIconColor: "success",
                            title: outcome.text,
                        }))}
                    />
                )] : []),
            ]}
        />
    )
}

export { ContentHeader }

import React from "react"
import { PageHeader } from "@sb-components/composites/layout/Page/Page"
import { type SkeletonProps } from "@sb-components/frames/_slot"
import { Breadcrumbs } from "@sb-components/atoms/navigation/Breadcrumbs/Breadcrumbs"
import { Typography } from "@sb-components/atoms/text/Typography/Typography"

/**
 * `CourseBrief` — the course-identity cluster atop a page. It takes crumb DATA
 * (`breadcrumbItems`) and builds the `Breadcrumbs` atom itself, so a screen
 * never holds the `PageHeader` frame or the atom directly. Meta is a muted text
 * strip joined by `·`, not a chip. The two leaves lose a node; a long trail only
 * changes the crumb count, so it is a state.
 */

/** One breadcrumb link — plain data, the block builds the atom from it. */
export interface CourseBriefCrumb {
    /** React key. */
    key: string
    /** Display label. */
    label: string
    /** Has a handler → crumb is pressable; the last crumb (current page) leaves it out. */
    onPress?: () => void
}

/** Props for {@link CourseBrief}. */
export interface CourseBriefBaseProps {
    /** Breadcrumb trail as DATA — the block builds `Breadcrumbs` itself. */
    breadcrumbItems?: Array<CourseBriefCrumb>
    /** Course name. */
    title: string
    /** One-sentence course description. */
    description?: string
    /**
     *  NO pre-formatted `meta` string prop.
     * Passing `meta="8 modules · ~14h · 2,481 learners"` is **breaking the
     * structure**: the caller ends up deciding the join, units, and separator —
     * the block loses ownership of its own shape. Below are separate NUMBER
     * fields; the block joins them itself into a muted strip separated by `·`.
     */
    moduleCount?: number
    /** Total learning hours (rounded) — the block adds `~` and the "hours" word itself. */
    hours?: number
    /** Number of enrolled learners — the block formats the thousands separator itself. */
    learnerCount?: number
    /**
     * `true` → the cluster switches to a mirror shimmer INSTEAD OF waiting for
     * data — the flag FLOWS DOWN to the actual text-rendering atoms/frames
     * (`PageHeader`/`Breadcrumbs`/`Typography`), not a parallel skeleton tree
     * (§12c). `PageHeader` owns `isSkeleton` itself now (it swaps
     * `title`/`description` to shimmer internally), so this block just
     * forwards the flag straight through.
     */
    isSkeleton?: boolean
}

/**
 * Course identity cluster at the top of a page. See the file header for the
 * full contract.
 *
 * @param props - {@link CourseBriefBaseProps}
 */
const CourseBriefBase = ({
    breadcrumbItems,
    title,
    description,
    moduleCount,
    hours,
    learnerCount,
    isSkeleton = false,
}: CourseBriefBaseProps) => {
    // Meta strip joined by the BLOCK from NUMBERS — units, separators, thousands
    // grouping are all presentation; the caller doesn't touch this (§14d.1).
    const metaParts = [
        moduleCount != null ? `${moduleCount} modules` : null,
        hours != null ? `~${hours} hours` : null,
        learnerCount != null ? `${learnerCount.toLocaleString("vi-VN")} learners` : null,
    ].filter(Boolean)

    return (
        // Identity hold: PageHeader does not accept CallerIdentity (ledger PageHeader gap).
        <PageHeader
            isSkeleton={isSkeleton}
            breadcrumb={
                breadcrumbItems?.length
                    ? ({ isSkeleton: skeleton }: SkeletonProps) => (
                        // Hold: no hug-width frame for breadcrumb measure (`w-fit` parent placement).
                        <div className="w-fit">
                            {/* collapse: below @app-sm or trail ≥ 4 crumbs → back-link (the old
                        capability of ResponsiveBreadcrumb, now a prop of the Breadcrumbs atom). */}
                            <Breadcrumbs
                                collapseOnMobile
                                collapseFrom={4}
                                items={breadcrumbItems ?? []}
                                isSkeleton={skeleton}
                            />
                        </div>
                    )
                    : undefined
            }
            title={title}
            description={description}
            meta={
                metaParts.length > 0
                    ? () => (
                        <Typography size="xs" color="muted" text={metaParts.join(" · ")} />
                    )
                    : undefined
            }
        />
    )
}

/** `CourseBrief.*` — single-component namespace ⇒ only `.Base`. */
export { CourseBriefBase as CourseBrief }

import React from "react"
import { BookOpenIcon, CodeIcon, FlaskIcon, PlayIcon, PuzzlePieceIcon } from "@phosphor-icons/react"
import { Toolbar, type ToolbarTabItem } from "@/components/composites/navigation/Toolbar"

/**
 * `ContentModeNav` — how to view this lesson: modes on the left, code language
 * on the right. Switching mode changes the route, so this is navigation, not a
 * tab/panel pair. A locked mode renders muted but still fires `onModeChange` —
 * the screen decides a locked tap opens the paywall. The mode group carries the
 * one accent; the language group is neutral. No `isSkeleton` — it is static
 * chrome. The right group appearing is its own leaf; selected mode and lock
 * state are data.
 */

/** The ways a lesson can be looked at. */
export type ContentMode = "content" | "sandbox" | "challenges" | "aiLab"

/**
 * Label + icon per mode. The BLOCK owns this table: it is the vocabulary of the
 * reading experience, and a caller that could pass it would own the wording.
 */
const MODE_LABEL: Record<ContentMode, string> = {
    content: "Content",
    sandbox: "Sandbox",
    challenges: "Challenges",
    aiLab: "AI Lab",
}

// `size-5` — the tab's own text is `text-sm` (HeroUI `Tabs.Tab` default, `tabs.css`
// `.apply ... text-sm`), and this icon sits INSIDE that control, so it matches the
// control's own box height (line-height 20px), not the bare glyph size (§5a icon=DIV
// case) — `size-3.5` would be the icon=TEXT pairing, wrong for an icon inside a tab.
const MODE_ICON: Record<ContentMode, React.ReactNode> = {
    content: <BookOpenIcon aria-hidden focusable="false" className="size-5" />,
    sandbox: <PlayIcon aria-hidden focusable="false" className="size-5" />,
    challenges: <PuzzlePieceIcon aria-hidden focusable="false" className="size-5" />,
    aiLab: <FlaskIcon aria-hidden focusable="false" className="size-5" />,
}

// Same icon on every language tab (doesn't distinguish TS from Go) — the trigger
// affordance for "this collapses to a language switcher" below `@app-sm`, not a
// per-language mark. Matches `Toolbar`'s own collapsed-group story convention
// (`RightNeutralCollapsed`, every item sharing one `GlobeIcon`) — the collapsed
// `Select` trigger is ICON-ONLY (§13c), so a language row with no icon of its own
// would render a blank trigger once `collapseRightOnMobile` is on.
const LANGUAGE_ICON = <CodeIcon aria-hidden focusable="false" className="size-4" weight="bold" />

/** One offered mode — whether it is locked. */
export interface ContentModeOption {
    /** Which mode this entry is. */
    mode: ContentMode
    /** `true` → premium and not yet bought: rendered muted, still clickable. */
    isLocked?: boolean
}

/** One entry in the fixed code-language catalog. */
export interface ContentLanguage {
    /** Stable id used as the selection key, e.g. `"typescript"`. */
    key: string
    /** Display label, already localized by the caller. */
    label: string
    /** `true` → this lesson has no body in this language: rendered disabled, not omitted. */
    isDisabled?: boolean
}

/** Props for {@link ContentModeNav}. */
export interface ContentModeNavProps {
    /** Modes this lesson offers, in display order. */
    modes: Array<ContentModeOption>
    /** Which mode is being looked at now. */
    mode: ContentMode
    /**
     * Fired with the mode the reader picked — INCLUDING a locked one. The screen
     * decides what a locked pick means (typically: open the paywall instead of
     * navigating). The block never swallows the event.
     */
    onModeChange: (mode: ContentMode) => void
    /**
     * The FULL fixed language catalog (TypeScript/Java/C#/Go, in that order),
     * each carrying its own `isDisabled` — a lesson missing a language still
     * lists it, dimmed, rather than shrinking the row (real `src` never hides
     * a language, only greys it out). Fewer than two AVAILABLE (non-disabled)
     * entries → the right group is not drawn at all: a switcher with one live
     * option is a control that cannot do anything.
     */
    languages?: Array<ContentLanguage>
    /** Which language is being read. */
    language?: string
    /** Fired with the language the reader picked. */
    onLanguageChange?: (language: string) => void
    /**
     * Accessible name for the mode row, localized by the caller (blocks carry no
     * i18n). Without it a screen reader hears loose tabs.
     */
    ariaLabel: string
    /** Accessible name for the language group. Required whenever `languages` is set. */
    languageAriaLabel?: string
}

/**
 * The lesson's mode row. See the file header for why locked modes stay clickable
 * and why this is navigation rather than a tab/panel pair.
 *
 * @param props - {@link ContentModeNavProps}
 */
const ContentModeNav = ({
    modes,
    mode,
    onModeChange,
    languages,
    language,
    onLanguageChange,
    ariaLabel,
    languageAriaLabel,
}: ContentModeNavProps) => {
    const items: Array<ToolbarTabItem> = modes.map((entry) => ({
        key: entry.mode,
        label: MODE_LABEL[entry.mode],
        icon: MODE_ICON[entry.mode],
        // MUTED, not disabled: a locked mode must still receive the click so the
        // screen can open the offer. Disabling it kills the very thing this row is for.
        muted: entry.isLocked,
    }))

    // A switcher with one AVAILABLE option is a control that cannot do anything — count
    // only the non-disabled entries, since the catalog itself always lists all four.
    const availableLanguageCount = (languages ?? []).filter((entry) => !entry.isDisabled).length
    const hasLanguages = availableLanguageCount > 1 && language != null && onLanguageChange != null

    // Identity hold: Toolbar does not accept CallerIdentity.
    return (
        <Toolbar
            leftTabs={{
                items,
                selectedKey: mode,
                ariaLabel,
                onSelectionChange: (key) => onModeChange(String(key) as ContentMode),
            }}
            rightTabs={
                hasLanguages
                    ? {
                        items: (languages ?? []).map((entry) => ({
                            key: entry.key,
                            label: entry.label,
                            icon: LANGUAGE_ICON,
                            isDisabled: entry.isDisabled,
                        })),
                        selectedKey: language as string,
                        ariaLabel: languageAriaLabel ?? "",
                        onSelectionChange: (key) => onLanguageChange?.(String(key)),
                    }
                    : undefined
            }
            // The language group is a "same lesson, different presentation" toggle, so
            // it stays NEUTRAL: only the mode group carries accent, and the row keeps
            // ONE accent signal rather than two competing for the eye.
            rightTabsNeutral
            // A set-once preference, not a second navigation choice — folds behind a
            // compact icon-only dropdown below `@app-sm` instead of crowding the reading
            // column with 4 inline tabs.
            collapseRightOnMobile
        />
    )
}

export { ContentModeNav }

